220	    pub fn extract_usize(&self) -> PolarsResult<usize> {
221	        macro_rules! cast_usize {
222	            ($v:expr) => {
223	                usize::try_from($v).map_err(
224	                    |_| polars_err!(InvalidOperation: "cannot convert value {} to usize", $v)
225	                )
226	            }
227	        }
228	        match &self {
229	            Self::Dyn(DynLiteralValue::Int(v)) => cast_usize!(*v),
