34	    // Floats are handled separately: they have a total order, but NaN values are excluded from
35	    // Parquet statistics, which makes several comparisons unsafe for skipping batches. See the
36	    // individual comparison branches for the NaN-aware handling.
37	    !dtype.is_nested() && !dtype.is_float() && !dtype.is_null() && !dtype.is_categorical()
38	}
